class Solution { vector<vector<int>> events,memo;int nextIndex(int end){int left=0,right=events.size();while(left<right){int mid=(left+right)/2;if(events[mid][0]<=end)left=mid+1;else right=mid;}return left;}int dfs(int index,int remaining){if(index==(int)events.size()||!remaining)return 0;int& answer=memo[index][remaining];if(answer>=0)return answer;return answer=max(dfs(index+1,remaining),events[index][2]+dfs(nextIndex(events[index][1]),remaining-1));}public:int maxValue(vector<vector<int>>& input,int k){events=input;sort(events.begin(),events.end());memo.assign(events.size(),vector<int>(k+1,-1));return dfs(0,k);} };
